/* Adam's Learning Adventure — service worker (generated by scripts/build-sw.mjs). */
const VERSION = '__VERSION__';
/** url → content revision for every file of the static export */
const REVISIONS = __REVISIONS__;
/** urls without which the install fails (the previous worker then stays active) */
const CRITICAL = __CRITICAL__;

const SHELL = `adam-shell-${VERSION}`; // app shell + code: one cache per version
const AUDIO = 'adam-audio'; // long-lived: audio survives code-only deploys untouched
const META = 'adam-meta'; // revision bookkeeping
const META_AUDIO = '/__adam/audio-revisions';
const META_SHELL = '/__adam/shell';
const LEGACY_PREFIX = 'adam-precache-';
const CONCURRENCY = 6;
const RETRIES = 2;

const isAudio = (url) => url.startsWith('/audio/');
const cacheFor = (url) => (isAudio(url) ? AUDIO : SHELL);

async function readMeta(key) {
  try {
    const res = await (await caches.open(META)).match(key);
    return res ? await res.json() : null;
  } catch {
    return null;
  }
}

async function writeMeta(key, value) {
  const meta = await caches.open(META);
  await meta.put(key, new Response(JSON.stringify(value), { headers: { 'content-type': 'application/json' } }));
}

async function fetchWithRetry(url) {
  let lastErr;
  for (let attempt = 0; attempt <= RETRIES; attempt++) {
    try {
      const res = await fetch(new Request(url, { cache: 'reload' }));
      if (res.ok) return res;
      lastErr = new Error(`${url}: HTTP ${res.status}`);
    } catch (e) {
      lastErr = e;
    }
    await new Promise((r) => setTimeout(r, 400 * (attempt + 1)));
  }
  throw lastErr;
}

async function pool(items, worker) {
  let i = 0;
  const run = async () => {
    while (i < items.length) await worker(items[i++]);
  };
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, items.length) }, run));
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const shell = await caches.open(SHELL);
      const audio = await caches.open(AUDIO);
      const audioRevs = (await readMeta(META_AUDIO)) ?? {};
      const prevShell = await readMeta(META_SHELL); // { cache, revs }
      const prevShellCache = prevShell && prevShell.cache !== SHELL ? await caches.open(prevShell.cache) : null;
      const newAudioRevs = {};
      const failed = [];
      let copied = 0;
      let fetched = 0;

      await pool(Object.keys(REVISIONS), async (url) => {
        const rev = REVISIONS[url];
        const target = isAudio(url) ? audio : shell;
        // 1. unchanged + already stored → keep / copy, no network
        if (isAudio(url)) {
          if (audioRevs[url] === rev && (await audio.match(url))) {
            newAudioRevs[url] = rev;
            copied++;
            return;
          }
        } else {
          if (await shell.match(url)) return; // re-run of this same install
          if (prevShellCache && prevShell.revs[url] === rev) {
            const old = await prevShellCache.match(url);
            if (old) {
              await shell.put(url, old);
              copied++;
              return;
            }
          }
        }
        // 2. changed or missing → network (with retries)
        try {
          const res = await fetchWithRetry(url);
          await target.put(url, res);
          if (isAudio(url)) newAudioRevs[url] = rev;
          fetched++;
        } catch {
          failed.push(url);
        }
      });

      // keep the audio bookkeeping truthful even if we fail below (failed fetches keep the old
      // revision, which matches what is still stored)
      await writeMeta(META_AUDIO, { ...audioRevs, ...newAudioRevs });

      // Audio lives in a shared cache, so an older copy may be present: a critical audio entry
      // only counts when the stored copy has THIS build's revision.
      const storedAudioRevs = { ...audioRevs, ...newAudioRevs };
      const missingCritical = [];
      for (const url of CRITICAL) {
        const ok = isAudio(url)
          ? storedAudioRevs[url] === REVISIONS[url] && !!(await audio.match(url))
          : !!(await shell.match(url));
        if (!ok) missingCritical.push(url);
      }
      if (missingCritical.length) {
        // Abort: the previous worker (and its complete cache) stays in charge.
        await caches.delete(SHELL);
        throw new Error(`precache incomplete: ${missingCritical.slice(0, 5).join(', ')}`);
      }
      const shellRevs = {};
      for (const [u, r] of Object.entries(REVISIONS)) if (!isAudio(u)) shellRevs[u] = r;
      await writeMeta(META_SHELL, { cache: SHELL, revs: shellRevs, version: VERSION });
      console.log(`[sw ${VERSION}] installed: ${copied} reused, ${fetched} downloaded, ${failed.length} deferred`);
      // first install activates immediately; updates wait for a safe moment (see register.ts)
      if (!self.registration.active) await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => (k.startsWith('adam-shell-') && k !== SHELL) || k.startsWith(LEGACY_PREFIX))
          .map((k) => caches.delete(k)),
      );
      // prune audio files no longer part of the game
      const audio = await caches.open(AUDIO);
      for (const req of await audio.keys()) {
        const path = new URL(req.url).pathname;
        if (!(path in REVISIONS)) await audio.delete(req);
      }
      await self.clients.claim();
    })(),
  );
});

/** Offline completeness for the Parent Zone. */
async function status() {
  const urls = Object.keys(REVISIONS);
  const shell = await caches.open(SHELL);
  const audio = await caches.open(AUDIO);
  const audioRevs = (await readMeta(META_AUDIO)) ?? {};
  let cached = 0;
  const missingCritical = [];
  for (const url of urls) {
    const hit = isAudio(url) ? audioRevs[url] === REVISIONS[url] && (await audio.match(url)) : await shell.match(url);
    if (hit) cached++;
    else if (CRITICAL.includes(url)) missingCritical.push(url);
  }
  return { version: VERSION, total: urls.length, cached, missingCritical: missingCritical.length };
}

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'SKIP_WAITING') self.skipWaiting();
  if (data.type === 'GET_STATUS' && event.ports && event.ports[0]) {
    const port = event.ports[0];
    status().then(
      (s) => port.postMessage(s),
      () => port.postMessage(null),
    );
  }
});

function shellFor(url) {
  return url.pathname.startsWith('/parent') ? '/parent/index.html' : '/index.html';
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: network-first (fresh when online), cached app shell when offline.
  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(req);
        } catch {
          const shell = await caches.open(SHELL);
          return (
            (await shell.match(url.pathname.endsWith('/') ? url.pathname + 'index.html' : url.pathname)) ||
            (await shell.match(shellFor(url))) ||
            (await caches.match('/index.html')) ||
            Response.error()
          );
        }
      })(),
    );
    return;
  }

  // Everything else: cache-first, then network. Precached files that failed during install are
  // stored on first successful network fetch, so the offline set heals over time.
  event.respondWith(
    (async () => {
      const path = url.pathname;
      const cache = await caches.open(cacheFor(path));
      const hit = (await cache.match(req, { ignoreSearch: path.endsWith('.txt') })) || (await caches.match(req));
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok && res.type === 'basic' && path in REVISIONS) {
          await cache.put(path, res.clone());
          if (isAudio(path)) {
            const revs = (await readMeta(META_AUDIO)) ?? {};
            revs[path] = REVISIONS[path];
            await writeMeta(META_AUDIO, revs);
          }
        }
        return res;
      } catch {
        return new Response('', { status: 504, statusText: 'offline' });
      }
    })(),
  );
});
